import {api,session} from './auth.js';
import {jobsView,bindJobs} from './seismic-processing-jobs.js';
import {openCloudCopy} from './workspace-cloud-copy.js';
let host,scope='',generation=0,remoteVersion=new Map(),busy=false,notice='';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const operators={detrend:{name:'Remove mean / trend',group:'Trace editing',parameters:{mode:'linear'}},bandpass:{name:'Bandpass filter',group:'Signal processing',parameters:{low:5,high:60,order:4}},resample:{name:'Anti-aliased resampling',group:'Signal processing',parameters:{up:1,down:2}},'static-shift':{name:'Apply reviewed statics',group:'Corrections',parameters:{shifts:[]}},nmo:{name:'NMO & stretch mute',group:'Velocity & stacking',parameters:{offsets:[],velocity:2000,maxStretch:.3}},stack:{name:'Weighted stack',group:'Velocity & stacking',parameters:{weights:null}},'fk-filter':{name:'FK velocity filter',group:'Signal processing',parameters:{spacing:25,minimumVelocity:1500}}};
const sources=()=>host.getState().ingestion?.datasets?.filter(d=>d.family==='seismic'&&d.active!==false)||[];
const state=()=>{const w=host.getState();w.seismicProcessing||={schemaVersion:1,books:[],activeBook:null};const s=w.seismicProcessing;if(s.books.length&&!s.books.some(b=>b.id===s.activeBook))s.activeBook=s.books[0].id;return s;};
const current=()=>state().books.find(b=>b.id===state().activeBook)||state().books[0];
const scopeCurrent=g=>g===generation&&scope===`${session.user?.uid}:${host.getProject()?.id}`;
const safe=fn=>async e=>{try{await fn(e);}catch(error){host.toast(error.message);}};
const changed=()=>{const b=current();if(b){b.dirty=true;b.validation=null;b.estimate=null;}host.save();host.render();};
export function configureProcessing(context){host=context;}
function normalize(){const next=`${session.user?.uid}:${host.getProject()?.id}`;if(next===scope)return;scope=next;generation++;remoteVersion=new Map();busy=false;notice='';if(host.getProject().storage==='cloud')queueMicrotask(refresh);}
async function refresh(){
 const g=generation,p=host.getProject();if(busy)return;busy=true;
 try{if(p.storage==='cloud'){
  const data=await api(`/api/projects/${p.id}/imports`);if(!scopeCurrent(g))return;host.getState().ingestion={...(host.getState().ingestion||{}),...data};
  const resources=await api(`/api/projects/${p.id}/seismic`);if(!scopeCurrent(g))return;remoteVersion=new Map(resources.sources.map(d=>[d.id,d.sourceVersion]));
  const saved=await api(`/api/projects/${p.id}/seismic/graphs`);if(!scopeCurrent(g))return;
  for(const r of saved.graphs){const local=state().books.find(b=>b.id===r.id);if(!local)state().books.push({id:r.id,name:'Processing graph',graph:r.graph,selected:r.graph.output,dirty:false});else if(!local.dirty)local.graph=r.graph;}
  const history=await api(`/api/projects/${p.id}/seismic/runs`);if(!scopeCurrent(g))return;
  for(const b of state().books){const runs=history.runs.filter(r=>r.estimate?.graphId===b.id);b.run=runs.find(r=>r.id===b.run?.id)||runs[0]||b.run;}
 }host.render();}catch(error){if(scopeCurrent(g))host.toast(error.message);}finally{if(scopeCurrent(g))busy=false;}
}
function newBook(did){const d=sources().find(s=>s.id===did);if(!d)throw new Error('Select an active seismic source.');const id=crypto.randomUUID(),b={id,name:d.name+' processing',dirty:true,selected:null,graph:{revision:0,sourceId:d.id,sourceVersion:remoteVersion.get(d.id)||d.sourceVersion||d.sourceSha256||`${d.importId}:${d.id}`,domain:'TWT',domainConfirmed:false,amplitudeUnit:'',nodes:[],output:'',notes:''},selection:{firstTrace:0,traceCount:Math.min(128,d.metadata?.traceCount||128),firstSample:0,sampleCount:Math.min(1000,d.metadata?.sampleCount||1000)}};state().books.push(b);state().activeBook=id;changed();}
function addStep(operator){const b=current();if(!b)throw new Error('Add a seismic source first.');const node={id:crypto.randomUUID(),operator,input:b.graph.output||'source',parameters:structuredClone(operators[operator].parameters)};b.graph.nodes.push(node);b.graph.output=node.id;b.selected=node.id;changed();}
function graphCanvas(b){
 if(!b)return '<div class="sw-empty"><h2>Build a seismic processing graph</h2><p>Choose a retained survey from the browser. Add processing steps, inspect their settings and connect their inputs.</p><button id="sp-import">Import seismic sources</button></div>';
 const n=b.graph.nodes,positions=new Map([['source',32],...n.map((s,i)=>[s.id,132+i*100])]);
 return `<div class="sp-canvas"><svg viewBox="0 0 700 ${Math.max(260,160+n.length*100)}" role="img" aria-label="Processing graph connections">${n.map(s=>`<path d="M 350 ${(positions.get(s.input)||32)+48} L 350 ${positions.get(s.id)}" fill="none" stroke="#87a9a3" stroke-width="2"/>`).join('')}<rect x="180" y="32" width="340" height="48" rx="6" fill="#e1efea"/><text x="350" y="61" text-anchor="middle" fill="#174c44">Retained original</text>${n.map(s=>`<g role="button" tabindex="0" data-sp-node="${s.id}" aria-label="Select ${esc(operators[s.operator]?.name||s.operator)}"><rect x="180" y="${positions.get(s.id)}" width="340" height="48" rx="6" fill="${b.selected===s.id?'#087c73':'white'}" stroke="#087c73"/><text x="350" y="${positions.get(s.id)+29}" text-anchor="middle" fill="${b.selected===s.id?'white':'#174c44'}">${esc(operators[s.operator]?.name||s.operator)}${b.graph.output===s.id?' · output':''}</text></g>`).join('')}</svg></div>`;
}
function properties(b){
 if(!b)return '<p>Select a source to create a processing workbook.</p>';
 const n=b.graph.nodes.find(n=>n.id===b.selected);
 return `<form id="sp-source"><label>Workbook name<input name="name" maxlength="120" value="${esc(b.name)}" required></label><label>Source domain<select name="domain"><option value="TWT" ${b.graph.domain==='TWT'?'selected':''}>Two-way time · seconds</option><option value="depth" ${b.graph.domain==='depth'?'selected':''}>Depth · metres</option></select></label><label>Recorded amplitude unit / meaning<input name="amplitudeUnit" maxlength="80" value="${esc(b.graph.amplitudeUnit)}" required></label><label><input name="domainConfirmed" type="checkbox" ${b.graph.domainConfirmed?'checked':''}> I reviewed the source domain and amplitude meaning</label><button>Apply source settings</button></form>${n?`<hr><form id="sp-step"><h3>${esc(operators[n.operator]?.name||n.operator)}</h3><label>Input step<select name="input"><option value="source">Retained original</option>${b.graph.nodes.filter(x=>x.id!==n.id).map(x=>`<option value="${x.id}" ${n.input===x.id?'selected':''}>${esc(operators[x.operator]?.name||x.operator)} · ${b.graph.nodes.indexOf(x)+1}</option>`).join('')}</select></label>${Object.entries(n.parameters).map(([k,v])=>`<label>${esc(k)}${typeof v==='string'?`<input name="${k}" value="${esc(v)}">`:typeof v==='number'?`<input type="number" step="any" name="${k}" value="${v}" required>`:`<textarea name="${k}" rows="3" aria-label="${esc(k)} array">${esc(JSON.stringify(v))}</textarea>`}</label>`).join('')}<button>Apply step settings</button><button type="button" id="sp-output">Use as graph output</button><button type="button" id="sp-remove">Remove step</button></form>`:'<p>Select a graph step to edit its inputs and parameters.</p>'}<p class="sub">Source: ${esc(b.graph.sourceId)} · version ${esc(b.graph.sourceVersion)}</p>`;
}
export function processingView(){
 normalize();const s=state(),b=current(),groups=[...new Set(Object.values(operators).map(o=>o.group))];
 return `<section class="sw sp" aria-label="Seismic processing workspace"><header class="sw-heading"><div><div class="study-kicker">SEISMIC PROCESSING</div><h1>${esc(host.getProject().name)}</h1><p>Versioned processing graphs · retained survey inputs</p></div><button id="sp-refresh">Refresh</button>${host.getProject().storage!=='cloud'?'<button id="sp-cloud-copy">Create Cloud copy…</button>':''}</header><nav class="sw-ribbon" aria-label="Seismic processing tools"><button id="sp-sources">${host.icon('data')}Sources</button>${groups.map(g=>`<details class="sp-menu"><summary>${esc(g)}</summary><div>${Object.entries(operators).filter(([,o])=>o.group===g).map(([id,o])=>`<button data-sp-add="${id}">${esc(o.name)}</button>`).join('')}</div></details>`).join('')}<button id="sp-validate">Validate graph</button><button id="sp-save">Save graph</button><button id="sp-export">Export recipe</button></nav><div class="sw-body"><aside class="sw-browser" aria-label="Processing sources"><header><strong>Surveys & inputs</strong></header>${sources().map(d=>`<button class="sw-source" data-sp-source="${esc(d.id)}"><strong>${esc(d.name)}</strong><small>Retained original</small></button>`).join('')||'<p>No retained seismic sources. Import a survey to start.</p>'}</aside><div class="sw-workspace"><nav class="sw-books" aria-label="Processing workbooks">${s.books.map(w=>`<button data-sp-book="${w.id}" aria-pressed="${w.id===b?.id}">${esc(w.name)}${w.dirty?' · draft':''}</button>`).join('')}</nav>${graphCanvas(b)}${jobsView(b)}</div><aside class="sw-properties" aria-label="Processing properties">${properties(b)}</aside></div><div class="sw-status" role="status">${esc(notice||b?.validation?.message||'Configure the graph and review source settings before validation.')}</div></section>`;
}
export function bindProcessing(){
 if(!$('.sp'))return;const b=current();
 bindJobs(host,b,changed);
 if($('#sp-cloud-copy'))$('#sp-cloud-copy').onclick=()=>openCloudCopy(host,'processing');
 $('#sp-refresh').onclick=refresh;$('#sp-sources').onclick=()=>host.openImporter({family:'seismic'});if($('#sp-import'))$('#sp-import').onclick=$('#sp-sources').onclick;
 document.querySelectorAll('[data-sp-source]').forEach(e=>e.onclick=safe(()=>newBook(e.dataset.spSource)));
 document.querySelectorAll('[data-sp-add]').forEach(e=>e.onclick=safe(()=>addStep(e.dataset.spAdd)));
 document.querySelectorAll('[data-sp-book]').forEach(e=>e.onclick=()=>{state().activeBook=e.dataset.spBook;notice='';host.save();host.render();});
 document.querySelectorAll('[data-sp-node]').forEach(e=>{e.onclick=()=>{b.selected=e.dataset.spNode;host.save();host.render();};e.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();e.onclick();}};});
 if($('#sp-source'))$('#sp-source').onsubmit=safe(e=>{e.preventDefault();const f=new FormData(e.target);b.name=f.get('name').trim();b.graph.domain=f.get('domain');b.graph.domainConfirmed=f.has('domainConfirmed');b.graph.amplitudeUnit=f.get('amplitudeUnit').trim();changed();});
 if($('#sp-step')){
  $('#sp-step').onsubmit=safe(e=>{e.preventDefault();const n=b.graph.nodes.find(n=>n.id===b.selected),f=new FormData(e.target),p={};for(const [k,v] of Object.entries(n.parameters))p[k]=typeof v==='number'?Number(f.get(k)):typeof v==='string'?f.get(k):JSON.parse(f.get(k));n.input=f.get('input');n.parameters=p;changed();});
  $('#sp-output').onclick=()=>{b.graph.output=b.selected;changed();};$('#sp-remove').onclick=safe(()=>{if(b.graph.nodes.some(n=>n.input===b.selected))throw new Error('Reconnect downstream steps before removing this input.');b.graph.nodes=b.graph.nodes.filter(n=>n.id!==b.selected);if(b.graph.output===b.selected)b.graph.output=b.graph.nodes.at(-1)?.id||'';b.selected=b.graph.output||null;changed();});
 }
 $('#sp-validate').onclick=safe(async()=>{if(!b)throw new Error('Choose a source and add a processing step.');if(host.getProject().storage!=='cloud')throw new Error('Create an explicit Cloud copy before server validation. Local source contents have not been uploaded.');const g=generation,result=await api(`/api/projects/${host.getProject().id}/seismic/graphs/validate`,{method:'POST',body:b.graph});if(!scopeCurrent(g))return;b.validation=result;host.save();host.render();});
 $('#sp-save').onclick=safe(async()=>{if(!b)throw new Error('Choose a seismic source first.');if(host.getProject().storage==='cloud'){const g=generation,r=await api(`/api/projects/${host.getProject().id}/seismic/graphs/${b.id}`,{method:'PUT',body:b.graph});if(!scopeCurrent(g))return;b.graph=r.graph;}b.dirty=false;host.save();host.render();host.toast('Processing graph saved.');});
 $('#sp-export').onclick=safe(()=>{if(!b)throw new Error('Choose a processing workbook first.');host.download('seismic-processing-recipe.json',new Blob([JSON.stringify({name:b.name,graph:b.graph,selection:b.selection},null,2)],{type:'application/json'}));});
}
